import {type ReactElement, useMemo} from 'react'
import invariant from 'tiny-invariant'

import {AvailableModel} from './AvailableModel'
import type {CustomKey, CustomModel} from '@github-ui/copilot-byok-settings/types'
import {EmptyState} from './EmptyState'
import type {CustomModelPolicy} from '../types'

export function AvailableModels({
  customKeys,
  customModels,
  customModelPolicy,
  onUpdateModels,
  publicKey,
  enterpriseSlug,
}: {
  customKeys: CustomKey[]
  customModels: CustomModel[]
  customModelPolicy: CustomModelPolicy
  onUpdateModels: () => void
  publicKey: string
  enterpriseSlug: string
}) {
  const customKeysById = useMemo(() => new Map(customKeys.map(key => [key.id, key])), [customKeys])

  return customKeys.length > 0 ? (
    <>
      {customModels.map(model => {
        const customKey = customKeysById.get(model.customKeyId)
        invariant(customKey, `Custom key with id ${model.customKeyId} not found for model ${model.slug}`)

        return (
          <AvailableModel
            key={model.id}
            customKey={customKey}
            model={model}
            onUpdateModel={onUpdateModels}
            enterpriseSlug={enterpriseSlug}
            modelAccessStatus={customModelPolicy[String(model.id)]}
          />
        )
      })}
    </>
  ) : (
    <EmptyState onSuccess={onUpdateModels} publicKey={publicKey} enterpriseSlug={enterpriseSlug} />
  )
}
