import {setBanner} from '@github-ui/page-banner'
import {Banner, Button} from '@primer/react'
import {useRef, useState} from 'react'

import {EditKeyDialog} from './EditKeyDialog'
import type {CustomKey} from '@github-ui/copilot-byok-settings/types'

export function EditCustomKeyButton({
  publicKey,
  customKey,
  onRefresh,
  enterpriseSlug,
  'aria-describedby': ariaDescribedby,
}: {
  publicKey: string
  customKey: CustomKey
  onRefresh?: () => void
  'aria-describedby'?: string
  enterpriseSlug: string
}) {
  const ref = useRef<HTMLButtonElement>(null)
  const [show, setShow] = useState(false)

  function onUpdateHandler() {
    setShow(false)
    setBanner(
      <Banner
        role="banner"
        title="Updated"
        variant="success"
        hideTitle
        description={
          <>
            Custom key &quot;<strong>{customKey.name}</strong>&quot; successfully updated.
          </>
        }
      />,
    )
    onRefresh?.()
  }

  function onDeleteHandler() {
    setBanner(
      <Banner
        role="banner"
        title="Deleted"
        variant="success"
        hideTitle
        description={
          <>
            Custom key &quot;<strong>{customKey.name}</strong>&quot; successfully deleted.
          </>
        }
      />,
    )
    onRefresh?.()
  }

  return (
    <>
      <Button ref={ref} onClick={() => setShow(true)} aria-describedby={ariaDescribedby}>
        Edit
      </Button>

      {show && (
        <EditKeyDialog
          anchorRef={ref}
          publicKey={publicKey}
          customKey={customKey}
          onClose={() => setShow(false)}
          onDelete={onDeleteHandler}
          onUpdate={onUpdateHandler}
          enterpriseSlug={enterpriseSlug}
        />
      )}
    </>
  )
}
