import {FormControl, Stack} from '@primer/react'
import {useId, useState} from 'react'

import type {ProviderDataFor} from '@github-ui/copilot-byok-settings/types'
import {ProviderModelSelectorPane} from '../ProviderModelSelectorPane'
import type {ProviderFieldProps} from '../types'
import {useAPIKey} from '@github-ui/copilot-byok-settings/hooks/use-api-key'
import {
  AwsAccessKeyField,
  AwsRegionField,
} from '@github-ui/copilot-byok-settings/components/providers/awsbedrock/AwsBedrockFields'
import {FormValidationNode} from '@github-ui/copilot-byok-settings/components/FormValidationNode'
import styles from '../../AddApiKeyDialog.module.css'

export function AwsBedrockFields({
  apiKey,
  publicKey,
  customKey,
  validation,
  isPending,
  setValidation,
  onSetAdditionalData,
  enterpriseSlug,
}: ProviderFieldProps<'awsbedrock'>) {
  const id = useId()
  const [accessKey, setAccessKey] = useAPIKey(publicKey || '')
  const [region, setRegion] = useState((customKey && customKey?.region) ?? 'us-west-2')
  const htmlForId = `${id}-model-selector`
  const ariaDescribedBy = `${id}-description`
  const providerData: ProviderDataFor<'awsbedrock'> = {
    provider: 'awsbedrock',
    accessKey: accessKey || '',
    region: region || '',
  }

  return (
    <>
      <AwsAccessKeyField
        setAccessKey={setAccessKey}
        isPending={isPending}
        customKey={customKey}
        validation={validation}
      />
      <AwsRegionField isPending={isPending} region={region} setRegion={setRegion} validation={validation} />
      <Stack.Item grow className={styles.ModelSelectorLayout}>
        <FormControl className="width-full" disabled={isPending}>
          <FormControl.Label htmlFor={htmlForId}>Available models</FormControl.Label>
          <ProviderModelSelectorPane
            provider="awsbedrock"
            customKeyId={customKey?.id}
            key={`awsbedrock-${apiKey}`}
            apiKey={apiKey}
            providerData={providerData}
            isPending={isPending}
            htmlForId={htmlForId}
            aria-describedby={ariaDescribedBy}
            setValidation={setValidation}
            onSetAdditionalData={onSetAdditionalData}
            enterpriseSlug={enterpriseSlug}
          />
          <FormValidationNode item={validation?.models} id={ariaDescribedBy} />
        </FormControl>
      </Stack.Item>
    </>
  )
}
